def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    if n >= 99:
        return 'D'
    last_me, last_opp = history[-1]
    my_def = sum(1 for a, b in history if a == 'D')
    opp_def = sum(1 for a, b in history if b == 'D')
    if my_def > 0:
        for i in range(len(history) - 1, -1, -1):
            if history[i][0] == 'D' and history[i][1] == 'C':
                retaliated = False
                for j in range(i + 1, len(history)):
                    if history[j][1] == 'D':
                        retaliated = True
                        break
                if not retaliated:
                    return 'D'
                break
    if opp_def == 0:
        return 'C'
    streak = 0
    for a, b in reversed(history):
        if b == 'D':
            streak += 1
        else:
            break
    if last_opp == 'C':
        return 'C'
    else:
        if streak >= 6:
            return 'D'
        if streak >= 3:
            return 'C'
        if n >= 2:
            prev_me, prev_opp = history[-2]
            if prev_me == 'D' and prev_opp == 'C':
                return 'C'
        if opp_def == 1 and my_def == 0:
            return 'C'
        return 'D'
